-- 032: noticias de octubre de 2026.
--
-- La primera es el Informe Local Voluntario de Boyacá frente a la Agenda 2030, con
-- los dos documentos publicados en website/assets/pdf/ods/. Las otras cuatro son las
-- publicaciones más recientes de la Secretaría de Planeación en Instagram
-- (@secplaneacionboyaca), recogidas con su fecha original y enlazadas a la fuente.
--
-- Idempotente por slug: volver a aplicarla no duplica ninguna noticia.

SET NAMES utf8mb4;

INSERT INTO news (observatory_id, title, slug, summary, body, source, image_url, published_at, content_status, created_by)
SELECT NULL, 'Boyacá presenta su Informe Local Voluntario frente a la Agenda 2030 de las Naciones Unidas', 'informe-local-voluntario-boyaca-agenda-2030', '«Nuestro Gran Plan es Sostenible» evalúa el avance del departamento en los Objetivos de Desarrollo Sostenible con series 2022-2025: el Índice de Pobreza Multidimensional bajó de 9,9 % a 6,4 %, y la inversión pública asociada a los ODS en 2025 llegó a 1,78 billones de pesos. Descargue aquí el informe y su anexo metodológico.', '<p>La Secretaría de Planeación de Boyacá publica el <strong>Informe Local Voluntario (ILV) del Departamento de Boyacá</strong>, «Nuestro Gran Plan es Sostenible», con el que el departamento rinde cuentas de su avance frente a la Agenda 2030 de las Naciones Unidas. Es un ejercicio voluntario: ningún nivel de gobierno obliga a un departamento a presentarlo, y Boyacá lo asume como ejercicio de transparencia y de coherencia entre el Plan Departamental de Desarrollo 2024-2027 «Nuestro Gran Plan es Boyacá» y los Objetivos de Desarrollo Sostenible.</p> <p>El informe se construye sobre series estadísticas de 2022 a 2025 y no se limita a reportar logros: también nombra las brechas que siguen abiertas.</p> <h3>Algunos resultados del periodo</h3> <ul> <li>El <strong>Índice de Pobreza Multidimensional bajó de 9,9 % en 2023 a 6,4 % en 2025</strong>, 4,6 puntos por debajo del promedio nacional (11,5 %), según el DANE.</li> <li>La <strong>cobertura de aseguramiento en salud supera el 90 %</strong> de la población.</li> <li>El puntaje promedio en las <strong>Pruebas Saber 11 fue de 261,5 puntos</strong>, 7,5 por encima del promedio nacional, y el 76,1 % de los docentes oficiales tiene formación de posgrado.</li> <li>Hay <strong>500.000 hectáreas de páramo protegidas</strong> en el departamento.</li> </ul> <h3>Cuánto se invirtió y en qué</h3> <p>La inversión pública ejecutada en 2025 asociada a los ODS analizados ascendió a <strong>$1.779.939.457.061</strong>. No está repartida por igual: tres objetivos concentran el grueso de los recursos.</p> <ul> <li><strong>ODS 4 · Educación de calidad:</strong> $1.210.112.357.118, canalizados por la estrategia «Tierra del Conocimiento».</li> <li><strong>ODS 3 · Salud y bienestar:</strong> $226.071.674.279 en los 123 municipios.</li> <li><strong>ODS 9 · Industria, innovación e infraestructura:</strong> $189.751.137.723 en infraestructura vial, conectividad digital e innovación agroindustrial y minera.</li> </ul> <h3>Cómo se relacionan los ODS entre sí</h3> <p>El informe viene acompañado de un anexo técnico, el <strong>Modelo de Interrelaciones ODS de Boyacá</strong>, que analiza 56 indicadores departamentales y 75 emparejamientos dirigidos entre indicadores, contrastando una hipótesis causal territorial con la evidencia estadística de las series 2022-2025. El modelo identifica dónde una política empuja a otra y dónde compiten entre sí —por ejemplo, cómo el gasto en salud reduce la mortalidad materna pero muestra tensiones temporales frente a la neonatal—, con el fin de pasar de una planeación sectorial aislada a una presupuestación por nexos.</p> <h3>Descargue los documentos</h3> <ul> <li><a href="assets/pdf/ods/informe-local-voluntario-boyaca.pdf" target="_blank" rel="noopener"> Informe Local Voluntario · «Nuestro Gran Plan es Sostenible»</a> (103 páginas, PDF)</li> <li><a href="assets/pdf/ods/modelo-interrelaciones-ods-boyaca.pdf" target="_blank" rel="noopener"> Modelo de Interrelaciones ODS de Boyacá · anexo metodológico</a> (55 páginas, PDF)</li> </ul> <p class="small text-muted">Los dos archivos se publican en una versión optimizada para lectura en pantalla. Para la versión en alta resolución, escriba a la Secretaría de Planeación Departamental.</p> <p><em>Fuente: Gobernación de Boyacá — Secretaría de Planeación Departamental, Equipo de Territorialización de los ODS.</em></p>', 'Gobernación de Boyacá – Secretaría de Planeación Departamental', 'uploads/cms/2026/10/ilv-boyaca-agenda-2030.jpg', '2026-10-05 09:00:00', 'published', NULL
WHERE NOT EXISTS (SELECT 1 FROM news WHERE slug='informe-local-voluntario-boyaca-agenda-2030');

INSERT INTO news (observatory_id, title, slug, summary, body, source, image_url, published_at, content_status, created_by)
SELECT NULL, 'Día de la Boyacensidad: homenaje a la Provincia Centro y V Día Departamental de la Papa', 'planeacion-boyacensidad-dia-de-la-papa-2026', 'La Secretaría de Planeación acompañó la celebración del Día de la Boyacensidad, con un reconocimiento a los municipios de la Provincia Centro, y la quinta versión del Día Departamental de la Papa.', '<p>La Secretaría de Planeación de Boyacá se unió a la celebración del <strong>Día de la Boyacensidad</strong>, rindiendo homenaje a la Provincia Centro y a sus municipios, y reconociendo la riqueza de sus territorios, su gastronomía, sus tradiciones y su gente.</p> <p>La jornada coincidió con la <strong>quinta versión del Día Departamental de la Papa</strong>, un reconocimiento al alimento que nace de los campos boyacenses y llega a las mesas de Colombia gracias al trabajo de los campesinos del departamento.</p> <p><em>Publicado por la Secretaría de Planeación de Boyacá el 2 de octubre de 2026. <a href="https://www.instagram.com/secplaneacionboyaca/p/DeAWANuIL0q/" target="_blank" rel="noopener">Ver la publicación original en Instagram</a>.</em></p>', 'Secretaría de Planeación de Boyacá (@secplaneacionboyaca)', 'uploads/cms/2026/10/planeacion-boyacensidad-papa-2026.jpg', '2026-10-02 10:00:00', 'published', NULL
WHERE NOT EXISTS (SELECT 1 FROM news WHERE slug='planeacion-boyacensidad-dia-de-la-papa-2026');

INSERT INTO news (observatory_id, title, slug, summary, body, source, image_url, published_at, content_status, created_by)
SELECT NULL, 'Avanza la conformación del Comité Regional de Ordenamiento Territorial (CROT) de Boyacá', 'planeacion-crot-ordenamiento-territorial-2026', 'La Dirección Geográfica lideró la preapertura del CROT con el Ministerio del Interior, la Región Central, la Asamblea de Boyacá, las universidades del departamento y el CDP. En el encuentro se presentaron los avances del diagnóstico del Plan de Ordenamiento Departamental.', '<p>Desde la Dirección Geográfica, la Secretaría de Planeación de Boyacá lideró la <strong>preapertura para la consolidación del Comité Regional de Ordenamiento Territorial (CROT)</strong>, con el acompañamiento del Ministerio del Interior, la Región Central, la Asamblea de Boyacá, las universidades del departamento y el Consejo Departamental de Planeación.</p> <p>En el encuentro se socializó la conformación, las funciones y el marco normativo del CROT, y se presentaron los <strong>avances del diagnóstico del Plan de Ordenamiento Departamental</strong>, instrumento que entra ahora en su fase de consolidación.</p> <p>En el próximo mes cada entidad definirá sus delegados para instalar formalmente esta mesa de trabajo, clave para planificar el futuro del territorio.</p> <p><em>Publicado por la Secretaría de Planeación de Boyacá el 29 de septiembre de 2026. <a href="https://www.instagram.com/secplaneacionboyaca/p/Dd5CK5-IDkL/" target="_blank" rel="noopener">Ver la publicación original en Instagram</a>.</em></p>', 'Secretaría de Planeación de Boyacá (@secplaneacionboyaca)', 'uploads/cms/2026/10/planeacion-crot-ordenamiento-territorial.jpg', '2026-09-29 10:00:00', 'published', NULL
WHERE NOT EXISTS (SELECT 1 FROM news WHERE slug='planeacion-crot-ordenamiento-territorial-2026');

INSERT INTO news (observatory_id, title, slug, summary, body, source, image_url, published_at, content_status, created_by)
SELECT (SELECT id FROM observatories WHERE slug='cti' LIMIT 1), 'XXIII Semana Científica de la Juan de Castellanos: nace el Hub Science JDC', 'planeacion-xxiii-semana-cientifica-juan-de-castellanos', 'La Secretaría de Planeación participó en la inauguración de la XXIII Semana Científica de la Fundación Universitaria Juan de Castellanos, que este año estrenó el Hub Science JDC como espacio de encuentro entre ciencia e investigación.', '<p>La Secretaría de Planeación de Boyacá participó en la inauguración de la <strong>XXIII Semana Científica de la Fundación Universitaria Juan de Castellanos</strong>, que este año llegó con <strong>Hub Science JDC</strong>, un nuevo espacio para conectar saberes, experiencias y conversaciones alrededor de la ciencia y la investigación.</p> <p>El encuentro contó con expertos invitados —entre ellos Juan Manuel Lopera, Mercedes Díaz Lagos y Carlos Alberto Peláez— y con una muestra inmersiva al mundo de la ciencia, la tecnología y la innovación.</p> <p>La Secretaría acompañó el espacio como aliada de las universidades del departamento, bajo la idea de que el conocimiento que transforma el territorio se construye en articulación con la academia.</p> <p><em>Publicado por la Secretaría de Planeación de Boyacá el 28 de septiembre de 2026. <a href="https://www.instagram.com/secplaneacionboyaca/p/Dd2E11_IPAN/" target="_blank" rel="noopener">Ver la publicación original en Instagram</a>.</em></p>', 'Secretaría de Planeación de Boyacá (@secplaneacionboyaca)', 'uploads/cms/2026/10/planeacion-semana-cientifica-jdc.jpg', '2026-09-28 10:00:00', 'published', NULL
WHERE NOT EXISTS (SELECT 1 FROM news WHERE slug='planeacion-xxiii-semana-cientifica-juan-de-castellanos');

INSERT INTO news (observatory_id, title, slug, summary, body, source, image_url, published_at, content_status, created_by)
SELECT (SELECT id FROM observatories WHERE slug='cti' LIMIT 1), '«Café por la CTeI de Boyacá»: segundo encuentro de articulación del CODECTI', 'planeacion-cafe-por-la-ctei-boyaca-2026', 'Instituciones, universidades y aliados se reunieron bajo el esquema de la cuádruple hélice para avanzar en las vacaciones científicas, la estrategia «Pequeños Científicos» y la jornada «Boyacá Transfiere: del conocimiento a la acción».', '<p>En la Fundación Universitaria Juan de Castellanos se realizó el <strong>segundo encuentro de «Café por la CTeI de Boyacá»</strong>, una jornada de diálogo y articulación estratégica que reúne a instituciones, universidades y aliados bajo el esquema de la cuádruple hélice, como parte del trabajo del <strong>CODECTI Boyacá</strong>.</p> <p>En la sesión se avanzó en temas como las <strong>vacaciones científicas</strong>, la estrategia <strong>«Pequeños Científicos»</strong> y la jornada de transferencia regional <strong>«Boyacá Transfiere: del conocimiento a la acción»</strong>.</p> <p>El propósito del espacio es seguir fortaleciendo el ecosistema científico e investigativo del departamento.</p> <p><em>Publicado por la Secretaría de Planeación de Boyacá el 24 de septiembre de 2026. <a href="https://www.instagram.com/secplaneacionboyaca/p/Ddr-61NILyt/" target="_blank" rel="noopener">Ver la publicación original en Instagram</a>.</em></p>', 'Secretaría de Planeación de Boyacá (@secplaneacionboyaca)', 'uploads/cms/2026/10/planeacion-cafe-por-la-ctei.jpg', '2026-09-24 10:00:00', 'published', NULL
WHERE NOT EXISTS (SELECT 1 FROM news WHERE slug='planeacion-cafe-por-la-ctei-boyaca-2026');
